"use client";

import { useState } from "react";
import { useCart } from "@/context/CartContext";
import { menuItems } from "@/data/menu-items";

const CATEGORIES = ["All", "Pizza", "Burger", "Platter", "Roll", "Sides"] as const;

export function OrderingGrid() {
  const { addItem } = useCart();
  const [activeCategory, setActiveCategory] = useState<(typeof CATEGORIES)[number]>("All");

  const filteredItems =
    activeCategory === "All"
      ? menuItems
      : menuItems.filter((item) => item.category === activeCategory);

  const getOriginalPriceDisplay = (priceNumber: number, itemId: string) => {
    if (itemId === "crown-crust") return "Rs. 1,799";
    // Fake "was" price for a high-conversion deal feeling.
    const original = Math.round(priceNumber * 1.25 / 10) * 10;
    return `Rs. ${original.toLocaleString("en-PK")}`;
  };

  return (
    <section className="mx-auto max-w-6xl px-4 pb-16 pt-6 md:px-6 md:pt-8">
      {/* Horizontal Category Bar */}
      <div className="mb-4 flex gap-2 overflow-x-auto pb-1 md:mb-6">
        {CATEGORIES.map((cat) => {
          const isActive = activeCategory === cat;
          return (
            <button
              key={cat}
              type="button"
              onClick={() => setActiveCategory(cat)}
              className={`whitespace-nowrap rounded-full border px-4 py-2 text-sm font-black uppercase tracking-[0.18em] transition-colors ${
                isActive
                  ? "border-cheez-red bg-cheez-red text-cheez-white"
                  : "border-cheez-red/20 bg-white/50 text-cheez-ink/80 backdrop-blur-xl hover:border-cheez-red hover:bg-white/70 hover:text-cheez-red"
              }`}
            >
              {cat}
            </button>
          );
        })}
      </div>

      {/* Food Cards Grid */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {filteredItems.map((item) => (
          <article
            key={item.id}
            className="group relative flex flex-col rounded-3xl border border-white/60 bg-white/40 p-4 shadow-[0_18px_45px_rgba(15,23,42,0.10)] backdrop-blur-xl transition-all duration-300 hover:-translate-y-1 hover:shadow-[0_30px_90px_rgba(229,57,53,0.18)]"
          >
            {item.id === "crown-crust" && (
              <div className="absolute right-3 top-3 rounded-full bg-[#FFB703] px-3 py-1 text-[10px] font-black uppercase tracking-[0.18em] text-cheez-ink shadow-sm">
                Most Loved
              </div>
            )}

            <div className="flex flex-1 flex-col gap-2 pt-2">
              <span className="inline-flex w-fit rounded-full bg-cheez-red/10 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-cheez-red">
                {item.category}
              </span>
              <h3 className="text-lg font-semibold text-cheez-ink">{item.name}</h3>
              {item.description && (
                <p className="text-sm text-cheez-ink/70 line-clamp-2">{item.description}</p>
              )}
            </div>
            <div className="mt-4 flex items-center justify-between gap-3">
              <div className="flex flex-col items-end leading-tight">
                <span className="text-xs font-semibold text-cheez-ink/45 line-through">
                  {getOriginalPriceDisplay(item.priceNumber, item.id)}
                </span>
                <span className="text-base font-black text-cheez-ink md:text-lg">
                  {item.priceDisplay}
                </span>
              </div>
              <button
                type="button"
                onClick={() => addItem(item)}
                className="flex h-10 w-10 items-center justify-center rounded-full bg-cheez-red text-base font-black text-cheez-white shadow-md transition-colors hover:bg-[#d52f3b] active:scale-[0.98]"
                aria-label={`Add ${item.name} to cart`}
              >
                +
              </button>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

